  <div id="task-alert" role="alert" hidden></div>
  <label for="task-filter">Task filter</label><select id="task-filter" aria-label="Task filter"><option>All</option><option>Open</option><option>Completed</option></select>
  <section class="task-list" aria-label="Tasks"></section>`;
app.querySelector('.back').addEventListener('click', () => {
  history.pushState({}, '', '/');
  showRoute();
});
const list = app.querySelector('.task-list');
const filter = app.querySelector('#task-filter');
async function renderTasks() {
  const tasks = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`).then(r => r.json());
  const visible = tasks.filter(task => filter.value === 'All' || (filter.value === 'Open' ? !task.completed : task.completed));
  list.innerHTML = visible.map(task => `<div data-testid="task-row"><input type="checkbox" data-task="${task.id}" aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''}><span>${escapeHtml(task.title)}</span></div>`).join('');
  list.querySelectorAll('[data-task]').forEach(box => box.addEventListener('change', async () => {
    await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${box.dataset.task}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: box.checked }) });
    renderTasks();
  }));
}
filter.addEventListener('change', renderTasks);
app.querySelector('#task-form').addEventListener('submit', async event => {
  event.preventDefault();
  const title = app.querySelector('#task-title').value.trim();
  if (!title) {
    const alert = app.querySelector('#task-alert');
    alert.textContent = 'Task title is required';
    alert.hidden = false;
    return;
  }
  const result = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
  if (result.ok) { app.querySelector('#task-title').value = ''; renderTasks(); }
});
renderTasks();

